import{_ as e,o as l,c as i,aw as t}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Загрузка веб-страницы","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/critical-rendering-path/optimization/website-loading.md","filePath":"wiki/dev-commit/js/critical-rendering-path/optimization/website-loading.md"}'),o={name:"wiki/dev-commit/js/critical-rendering-path/optimization/website-loading.md"};function s(r,a,n,c,p,d){return l(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="загрузка-веб-страницы" tabindex="-1">Загрузка веб-страницы <a class="header-anchor" href="#загрузка-веб-страницы" aria-label="Permalink to &quot;Загрузка веб-страницы&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>DNS (Domain Name Servers)</strong> - распределенная таблица где указано имя сайта (htmlacademy.ru) и его физический адрес (178.79.181.169)</li><li><strong>Служба доставки, протокол TCP/IP</strong> - доставляется контент от одного сервера до другого. Доставляет HTTP-пакеты</li></ul></div><h2 id="алгоритм" tabindex="-1">Алгоритм <a class="header-anchor" href="#алгоритм" aria-label="Permalink to &quot;Алгоритм&quot;">​</a></h2><h4 id="_1-ввод-адреса-в-браузере" tabindex="-1">1. Ввод адреса в браузере <a class="header-anchor" href="#_1-ввод-адреса-в-браузере" aria-label="Permalink to &quot;1. Ввод адреса в браузере&quot;">​</a></h4><ul><li>Пользователь вводит адрес, н-р: <a href="https://www.google.com/" target="_blank" rel="noreferrer">https://www.google.com/</a></li></ul><hr><h4 id="_2-определение-ip-адреса" tabindex="-1">2. Определение IP-адреса <a class="header-anchor" href="#_2-определение-ip-адреса" aria-label="Permalink to &quot;2. Определение IP-адреса&quot;">​</a></h4><p>Браузеру необходимо понять на какой IP-адрес ему делать GET-запрос</p><ol><li><em>Локальный кеш</em> - браузер пойдет в свой кэш - возможно, когда-то мы заходили на этот сайт и в кэше будет сохранена ассоциативная запись доменного имени и IP-адреса</li><li><em>DNS на сервере преобразует его в IP-адрес</em> - если в кэше его нет, то будет сделан запрос на ближайший DNS-сервер. Обычно это DNS-сервер локального провайдера и потом уже DNS-сервер вернет ассоциативную запись. Но если там нет, то пойдет дальше по цепочке на следующий DNS-сервер, пока не дойдет до корневого</li><li><em>Hosting Server</em></li><li><em>WebSite</em></li><li><em>Обратно пользователю</em></li></ol><hr><h4 id="_3-веб-сервер" tabindex="-1">3. Веб-сервер <a class="header-anchor" href="#_3-веб-сервер" aria-label="Permalink to &quot;3. Веб-сервер&quot;">​</a></h4><p><strong>Сайт</strong></p><ul><li>Сайт лежит на сервере</li></ul><p><strong>Сервер</strong></p><ul><li>У сервера есть IP-адрес</li><li>У сервера есть много портов</li></ul><p><strong>Порт</strong></p><ul><li>На сервере существует много портов и за каждый порт отвечает какая-то программа</li><li>Порт можно не писать, браузер сам понимает по какому порту обращаться</li><li>На одном порту может находиться много сайтов. Есть конфигурационный файл, который указыват имя сервера и директорию откуда брать сайт. Это называется виртуальный хост</li><li>Веб-сервер находится на этом порту</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">Сервер: </span><span style="color:#986801;">178.79</span><span style="color:#383A42;">.</span><span style="color:#986801;">181.169</span></span>
<span class="line"><span style="color:#383A42;">Порт: </span><span style="color:#986801;">80</span></span>
<span class="line"><span style="color:#383A42;">Сайт: google.</span><span style="color:#E45649;">com</span></span></code></pre></div><hr><h4 id="_4-получение-данных-страницы" tabindex="-1">4. Получение данных страницы <a class="header-anchor" href="#_4-получение-данных-страницы" aria-label="Permalink to &quot;4. Получение данных страницы&quot;">​</a></h4><ul><li>После того как браузер получит IP-адрес, он делает HTTP-запрос методом GET на получение данных для отрисовки страницы</li></ul><hr><h4 id="_5-критическии-путь-рендеринга" tabindex="-1">5. Критический путь рендеринга <a class="header-anchor" href="#_5-критическии-путь-рендеринга" aria-label="Permalink to &quot;5. Критический путь рендеринга&quot;">​</a></h4><ul><li>После получения ответа от сервера, браузер начинает выполнять критический путь рендеринга</li></ul>`,25)])])}const u=e(o,[["render",s]]);export{m as __pageData,u as default};
